import gcm_fast

class Solver:
    def solve(self, problem, **kwargs):
        ct, tag = gcm_fast.encrypt(
            problem["key"],
            problem["nonce"],
            problem["plaintext"],
            problem["associated_data"],
        )
        return {"ciphertext": ct, "tag": tag}

