#include <openssl/evp.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

static double now() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

int main() {
    size_t pt_len = 60000 * 1024;
    unsigned char *pt = malloc(pt_len);
    unsigned char *ct = malloc(pt_len + 16);
    unsigned char key[16], nonce[12], aad[32];
    memset(key, 1, 16);
    memset(nonce, 2, 12);
    memset(aad, 3, 32);
    memset(pt, 4, pt_len);

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    const EVP_CIPHER *cipher = EVP_aes_128_gcm();

    /* warmup */
    int len, ct_len;
    EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_SET_IVLEN, 12, NULL);
    EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
    EVP_EncryptUpdate(ctx, NULL, &len, aad, 32);
    EVP_EncryptUpdate(ctx, ct, &len, pt, pt_len);
    ct_len = len;
    EVP_EncryptFinal_ex(ctx, ct + len, &len);
    ct_len += len;
    unsigned char tag[16];
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_GET_TAG, 16, tag);

    double t0 = now();
    int iters = 5;
    for (int i = 0; i < iters; i++) {
        EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, NULL);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_SET_IVLEN, 12, NULL);
        EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
        EVP_EncryptUpdate(ctx, NULL, &len, aad, 32);
        EVP_EncryptUpdate(ctx, ct, &len, pt, pt_len);
        EVP_EncryptFinal_ex(ctx, ct + len, &len);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_GET_TAG, 16, tag);
    }
    double t1 = now();
    printf("C EVP GCM: %.4f s/iter  ct_len=%d tag0=%02x\n", (t1-t0)/iters, ct_len, tag[0]);

    /* reuse ctx without re-setting cipher */
    t0 = now();
    for (int i = 0; i < iters; i++) {
        EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
        EVP_EncryptUpdate(ctx, NULL, &len, aad, 32);
        EVP_EncryptUpdate(ctx, ct, &len, pt, pt_len);
        EVP_EncryptFinal_ex(ctx, ct + len, &len);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_GET_TAG, 16, tag);
    }
    t1 = now();
    printf("C EVP reuse: %.4f s/iter\n", (t1-t0)/iters);

    /* no AAD */
    t0 = now();
    for (int i = 0; i < iters; i++) {
        EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
        EVP_EncryptUpdate(ctx, ct, &len, pt, pt_len);
        EVP_EncryptFinal_ex(ctx, ct + len, &len);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_GET_TAG, 16, tag);
    }
    t1 = now();
    printf("C EVP no aad: %.4f s/iter\n", (t1-t0)/iters);

    EVP_CIPHER_CTX_free(ctx);
    free(pt); free(ct);
    return 0;
}
