{"command":"cd "$TMPDIR/gcm" && cat > bench_threads.c << 'EOF'
#include <openssl/evp.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

static double now() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

typedef struct {
    unsigned char *pt;
    unsigned char *ct;
    int len;
    unsigned char key[16];
    unsigned char nonce[12];
    unsigned char aad[32];
    int aad_len;
    unsigned char tag[16];
} job_t;

void *worker(void *arg) {
    job_t *j = arg;
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    int len;
    EVP_EncryptInit_ex(ctx, EVP_aes_128_gcm(), NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_SET_IVLEN, 12, NULL);
    EVP_EncryptInit_ex(ctx, NULL, NULL, j->key, j->nonce);
    if (j->aad_len)
        EVP_EncryptUpdate(ctx, NULL, &len, j->aad, j->aad_len);
    EVP_EncryptUpdate(ctx, j->ct, &len, j->pt, j->len);
    EVP_EncryptFinal_ex(ctx, j->ct + len, &len);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_GET_TAG, 16, j->tag);
    EVP_CIPHER_CTX_free(ctx);
    return NULL;
}

int main() {
    int nthreads = 6;
    size_t total = 60000 * 1024;
    size_t chunk = total / nthreads;
    unsigned char *pt = malloc(total);
    unsigned char *ct = malloc(total);
    memset(pt, 4, total);
    job_t jobs[8];
    pthread_t th[8];

    /* warmup */
    for (int i = 0; i < nthreads; i++) {
        jobs[i].pt = pt + i * chunk;
        jobs[i].ct = ct + i * chunk;
        jobs[i].len = (int)chunk;
        memset(jobs[i].key, 1, 16);
        memset(jobs[i].nonce, 2, 12);
        jobs[i].nonce[11] = (unsigned char)i; /* different nonce so not identical work... doesn't matter */
        memset(jobs[i].aad, 3, 32);
        jobs[i].aad_len = 32;
    }
    for (int i = 0; i < nthreads; i++) pthread_create(&th[i], NULL, worker, &jobs[i]);
    for (int i = 0; i < nthreads; i++) pthread_join(th[i], NULL);

    double t0 = now();
    int iters = 3;
    for (int it = 0; it < iters; it++) {
        for (int i = 0; i < nthreads; i++) pthread_create(&th[i], NULL, worker, &jobs[i]);
        for (int i = 0; i < nthreads; i++) pthread_join(th[i], NULL);
    }
    double t1 = now();
    printf("%d threads chunked (independent keys): %.4f s\n", nthreads, (t1-t0)/iters);

    /* 4 threads */
    nthreads = 4;
    chunk = total / nthreads;
    for (int i = 0; i < nthreads; i++) {
        jobs[i].pt = pt + i * chunk;
        jobs[i].ct = ct + i * chunk;
        jobs[i].len = (int)chunk;
    }
    t0 = now();
    for (int it = 0; it < iters; it++) {
        for (int i = 0; i < nthreads; i++) pthread_create(&th[i], NULL, worker, &jobs[i]);
        for (int i = 0; i < nthreads; i++) pthread_join(th[i], NULL);
    }
    t1 = now();
    printf("4 threads: %.4f s\n", (t1-t0)/iters);

    nthreads = 8;
    chunk = total / nthreads;
    for (int i = 0; i < nthreads; i++) {
        jobs[i].pt = pt + i * chunk;
        jobs[i].ct = ct + i * chunk;
        jobs[i].len = (int)chunk;
        memset(jobs[i].key, 1, 16);
        memset(jobs[i].nonce, 2, 12);
        jobs[i].aad_len = 32;
    }
    t0 = now();
    for (int it = 0; it < iters; it++) {
        for (int i = 0; i < nthreads; i++) pthread_create(&th[i], NULL, worker, &jobs[i]);
        for (int i = 0; i < nthreads; i++) pthread_join(th[i], NULL);
    }
    t1 = now();
    printf("8 threads: %.4f s\n", (t1-t0)/iters);

    /* single thread full */
    jobs[0].pt = pt; jobs[0].ct = ct; jobs[0].len = (int)total;
    t0 = now();
    for (int it = 0; it < iters; it++) worker(&jobs[0]);
    t1 = now();
    printf("1 thread full: %.4f s\n", (t1-t0)/iters);

    free(pt); free(ct);
    return 0;
}
EOF
