#include <openssl/evp.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

static double now() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

int main() {
    size_t pt_len = 60000UL * 1024;
    unsigned char *pt = malloc(pt_len);
    unsigned char *ct = malloc(pt_len);
    unsigned char key[16], iv[16];
    memset(key, 1, 16);
    memset(iv, 2, 16);
    memset(pt, 4, pt_len);

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    int len;

    /* warmup */
    EVP_EncryptInit_ex(ctx, EVP_aes_128_ctr(), NULL, key, iv);
    EVP_EncryptUpdate(ctx, ct, &len, pt, (int)pt_len);
    EVP_EncryptFinal_ex(ctx, ct + len, &len);

    double t0 = now();
    int iters = 5;
    for (int i = 0; i < iters; i++) {
        EVP_EncryptInit_ex(ctx, NULL, NULL, key, iv);
        EVP_EncryptUpdate(ctx, ct, &len, pt, (int)pt_len);
        EVP_EncryptFinal_ex(ctx, ct + len, &len);
    }
    printf("AES-CTR: %.4f s\n", (now()-t0)/iters);

    /* ECB */
    EVP_EncryptInit_ex(ctx, EVP_aes_128_ecb(), NULL, key, NULL);
    EVP_CIPHER_CTX_set_padding(ctx, 0);
    t0 = now();
    for (int i = 0; i < iters; i++) {
        EVP_EncryptInit_ex(ctx, NULL, NULL, key, NULL);
        EVP_CIPHER_CTX_set_padding(ctx, 0);
        EVP_EncryptUpdate(ctx, ct, &len, pt, (int)pt_len);
        EVP_EncryptFinal_ex(ctx, ct + len, &len);
    }
    printf("AES-ECB: %.4f s\n", (now()-t0)/iters);

    /* memcpy bandwidth */
    t0 = now();
    for (int i = 0; i < iters; i++) memcpy(ct, pt, pt_len);
    printf("memcpy: %.4f s  (%.1f GB/s)\n", (now()-t0)/iters, pt_len / ((now()-t0)/iters) / 1e9);

    /* read+write bandwidth: xor */
    t0 = now();
    for (int i = 0; i < iters; i++) {
        for (size_t j = 0; j < pt_len; j += 64) {
            /* touch */
            ct[j] = pt[j] ^ 1;
        }
    }
    printf("stride touch: %.4f s\n", (now()-t0)/iters);

    EVP_CIPHER_CTX_free(ctx);
    free(pt); free(ct);
    return 0;
}
EOF
