{"command":"cd "$TMPDIR/gcm" && cat > gcm_ext.c << 'EOF'
#define PY_SSIZE_T_CLEAN
#include <Python.h>
#include <openssl/evp.h>
#include <pthread.h>
#include <string.h>
#include <stdlib.h>

typedef struct {
    const unsigned char *pt;
    unsigned char *ct;
    int len;
    const unsigned char *key;
    int key_len;
    const unsigned char *nonce;
    int nonce_len;
    const unsigned char *aad;
    int aad_len;
    unsigned char *tag;
    const EVP_CIPHER *cipher;
    int rc;
} job_t;

static void do_job(job_t *j) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) { j->rc = -1; return; }
    int len = 0, fin = 0;
    if (EVP_EncryptInit_ex(ctx, j->cipher, NULL, NULL, NULL) != 1) { j->rc = -2; goto done; }
    if (EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_SET_IVLEN, j->nonce_len, NULL) != 1) { j->rc = -3; goto done; }
    if (EVP_EncryptInit_ex(ctx, NULL, NULL, j->key, j->nonce) != 1) { j->rc = -4; goto done; }
    if (j->aad && j->aad_len) {
        if (EVP_EncryptUpdate(ctx, NULL, &len, j->aad, j->aad_len) != 1) { j->rc = -5; goto done; }
    }
    if (EVP_EncryptUpdate(ctx, j->ct, &len, j->pt, j->len) != 1) { j->rc = -6; goto done; }
    if (EVP_EncryptFinal_ex(ctx, j->ct + len, &fin) != 1) { j->rc = -7; goto done; }
    if (EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_GET_TAG, 16, j->tag) != 1) { j->rc = -8; goto done; }
    j->rc = 0;
done:
    EVP_CIPHER_CTX_free(ctx);
}

static void *worker(void *arg) {
    do_job((job_t *)arg);
    return NULL;
}

static const EVP_CIPHER *pick_cipher(int key_len) {
    if (key_len == 16) return EVP_aes_128_gcm();
    if (key_len == 24) return EVP_aes_192_gcm();
    if (key_len == 32) return EVP_aes_256_gcm();
    return NULL;
}

/* encrypt(key, nonce, pt, aad, nthreads) -> (ct, tag) */
static PyObject *gcm_encrypt(PyObject *self, PyObject *args) {
    Py_buffer key, nonce, pt, aad;
    int nthreads = 1;
    int aad_is_none = 0;
    if (!PyArg_ParseTuple(args, "y*y*y*y*|i", &key, &nonce, &pt, &aad, &nthreads)) {
        /* try with None aad */
        PyErr_Clear();
        PyObject *aad_obj = NULL;
        if (!PyArg_ParseTuple(args, "y*y*y*O|i", &key, &nonce, &pt, &aad_obj, &nthreads))
            return NULL;
        if (aad_obj == Py_None) {
            aad.buf = NULL; aad.len = 0; aad_is_none = 1;
        } else {
            if (PyObject_GetBuffer(aad_obj, &aad, PyBUF_SIMPLE) != 0) {
                PyBuffer_Release(&key); PyBuffer_Release(&nonce); PyBuffer_Release(&pt);
                return NULL;
            }
        }
    }
    const EVP_CIPHER *cipher = pick_cipher((int)key.len);
    if (!cipher) {
        PyErr_SetString(PyExc_ValueError, "bad key length");
        goto fail;
    }
    if (nthreads < 1) nthreads = 1;
    if (nthreads > 16) nthreads = 16;
    if ((size_t)nthreads > (size_t)pt.len && pt.len > 0) nthreads = (int)pt.len;

    PyObject *ct_obj = PyBytes_FromStringAndSize(NULL, pt.len);
    PyObject *tag_obj = PyBytes_FromStringAndSize(NULL, 16);
    if (!ct_obj || !tag_obj) { Py_XDECREF(ct_obj); Py_XDECREF(tag_obj); goto fail; }
    unsigned char *ct = (unsigned char *)PyBytes_AS_STRING(ct_obj);
    unsigned char *tag = (unsigned char *)PyBytes_AS_STRING(tag_obj);

    if (nthreads == 1 || pt.len < 1024 * 1024) {
        job_t j = {
            .pt = pt.buf, .ct = ct, .len = (int)pt.len,
            .key = key.buf, .key_len = (int)key.len,
            .nonce = nonce.buf, .nonce_len = (int)nonce.len,
            .aad = aad.buf, .aad_len = (int)aad.len,
            .tag = tag, .cipher = cipher, .rc = 0
        };
        Py_BEGIN_ALLOW_THREADS
        do_job(&j);
        Py_END_ALLOW_THREADS
        if (j.rc != 0) {
            Py_DECREF(ct_obj); Py_DECREF(tag_obj);
            PyErr_Format(PyExc_RuntimeError, "gcm failed %d", j.rc);
            goto fail;
        }
    } else {
        /* Split plaintext into nthreads chunks (16-byte aligned except last).
           NOTE: this is NOT a correct single GCM; used only for timing experiments
           if we later stitch. For correctness we only use nthreads==1 in production.
           Here we still compute independent GCMs just to time parallelism of the primitive
           on slices — caller must not use nthreads>1 for real answers. */
        int n = nthreads;
        size_t chunk = ((size_t)pt.len / n) & ~(size_t)15;
        if (chunk == 0) chunk = (size_t)pt.len;
        job_t jobs[16];
        pthread_t th[16];
        unsigned char tags[16][16];
        int actual = 0;
        size_t off = 0;
        while (off < (size_t)pt.len && actual < n) {
            size_t len = (actual == n - 1) ? ((size_t)pt.len - off) : chunk;
            if (off + len > (size_t)pt.len) len = (size_t)pt.len - off;
            jobs[actual] = (job_t){
                .pt = (unsigned char *)pt.buf + off,
                .ct = ct + off,
                .len = (int)len,
                .key = key.buf, .key_len = (int)key.len,
                .nonce = nonce.buf, .nonce_len = (int)nonce.len,
                .aad = aad.buf, .aad_len = (int)aad.len,
                .tag = tags[actual], .cipher = cipher, .rc = 0
            };
            off += len;
            actual++;
            if (off >= (size_t)pt.len) break;
        }
        Py_BEGIN_ALLOW_THREADS
        for (int i = 0; i < actual; i++) pthread_create(&th[i], NULL, worker, &jobs[i]);
        for (int i = 0; i < actual; i++) pthread_join(th[i], NULL);
        Py_END_ALLOW_THREADS
        memcpy(tag, tags[0], 16);
    }

    PyBuffer_Release(&key); PyBuffer_Release(&nonce); PyBuffer_Release(&pt);
    if (!aad_is_none) PyBuffer_Release(&aad);
    return Py_BuildValue("(NN)", ct_obj, tag_obj);

fail:
    PyBuffer_Release(&key); PyBuffer_Release(&nonce); PyBuffer_Release(&pt);
    if (!aad_is_none) PyBuffer_Release(&aad);
    return NULL;
}

static PyMethodDef methods[] = {
    {"encrypt", gcm_encrypt, METH_VARARGS, "AES-GCM encrypt"},
    {NULL, NULL, 0, NULL}
};
static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT, "gcm_ext", NULL, -1, methods
};
PyMODINIT_FUNC PyInit_gcm_ext(void) { return PyModule_Create(&moduledef); }
EOF
