#include <Python.h>
#include <openssl/evp.h>
#include <string.h>

static const EVP_CIPHER *pick_cipher(Py_ssize_t key_len) {
    if (key_len == 16) return EVP_aes_128_gcm();
    if (key_len == 24) return EVP_aes_192_gcm();
    if (key_len == 32) return EVP_aes_256_gcm();
    return NULL;
}

/* encrypt(key, nonce, plaintext, aad_or_None) -> (ciphertext_bytes, tag_bytes)
   Writes directly into the result bytes objects. Releases the GIL. */
static PyObject *encrypt(PyObject *self, PyObject *args) {
    PyObject *key_obj, *nonce_obj, *pt_obj, *aad_obj;
    if (!PyArg_ParseTuple(args, "OOOO", &key_obj, &nonce_obj, &pt_obj, &aad_obj))
        return NULL;

    Py_buffer key, nonce, pt, aad;
    memset(&aad, 0, sizeof(aad));
    int have_aad = 0;
    if (PyObject_GetBuffer(key_obj, &key, PyBUF_SIMPLE) != 0) return NULL;
    if (PyObject_GetBuffer(nonce_obj, &nonce, PyBUF_SIMPLE) != 0) { PyBuffer_Release(&key); return NULL; }
    if (PyObject_GetBuffer(pt_obj, &pt, PyBUF_SIMPLE) != 0) {
        PyBuffer_Release(&key); PyBuffer_Release(&nonce); return NULL;
    }
    if (aad_obj != Py_None) {
        if (PyObject_GetBuffer(aad_obj, &aad, PyBUF_SIMPLE) != 0) {
            PyBuffer_Release(&key); PyBuffer_Release(&nonce); PyBuffer_Release(&pt); return NULL;
        }
        have_aad = 1;
    }

    const EVP_CIPHER *cipher = pick_cipher(key.len);
    if (!cipher || pt.len > 0x7fffffff) {
        PyErr_SetString(PyExc_ValueError, "unsupported key size or plaintext too large");
        goto fail;
    }

    PyObject *ct_obj = PyBytes_FromStringAndSize(NULL, pt.len);
    PyObject *tag_obj = PyBytes_FromStringAndSize(NULL, 16);
    if (!ct_obj || !tag_obj) { Py_XDECREF(ct_obj); Py_XDECREF(tag_obj); goto fail; }

    unsigned char *ct = (unsigned char *)PyBytes_AS_STRING(ct_obj);
    unsigned char *tag = (unsigned char *)PyBytes_AS_STRING(tag_obj);
    int rc = 0;

    Py_BEGIN_ALLOW_THREADS
    {
        EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
        int len = 0, fin = 0;
        if (!ctx) rc = -1;
        else if (EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, NULL) != 1) rc = -2;
        else if (EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_SET_IVLEN, (int)nonce.len, NULL) != 1) rc = -3;
        else if (EVP_EncryptInit_ex(ctx, NULL, NULL, key.buf, nonce.buf) != 1) rc = -4;
        else if (have_aad && aad.len && EVP_EncryptUpdate(ctx, NULL, &len, aad.buf, (int)aad.len) != 1) rc = -5;
        else if (pt.len && EVP_EncryptUpdate(ctx, ct, &len, pt.buf, (int)pt.len) != 1) rc = -6;
        else if (EVP_EncryptFinal_ex(ctx, ct + (pt.len ? len : 0), &fin) != 1) rc = -7;
        else if (EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_GET_TAG, 16, tag) != 1) rc = -8;
        EVP_CIPHER_CTX_free(ctx);
    }
    Py_END_ALLOW_THREADS

    PyBuffer_Release(&key); PyBuffer_Release(&nonce); PyBuffer_Release(&pt);
    if (have_aad) PyBuffer_Release(&aad);

    if (rc != 0) {
        Py_DECREF(ct_obj); Py_DECREF(tag_obj);
        PyErr_Format(PyExc_RuntimeError, "AES-GCM failed (%d)", rc);
        return NULL;
    }
    return PyTuple_Pack(2, ct_obj, tag_obj);

fail:
    PyBuffer_Release(&key); PyBuffer_Release(&nonce); PyBuffer_Release(&pt);
    if (have_aad) PyBuffer_Release(&aad);
    return NULL;
}

static PyMethodDef methods[] = {
    {"encrypt", encrypt, METH_VARARGS, NULL},
    {NULL, NULL, 0, NULL}
};
static struct PyModuleDef moduledef = {PyModuleDef_HEAD_INIT, "gcm_fast", NULL, -1, methods};
PyMODINIT_FUNC PyInit_gcm_fast(void) { return PyModule_Create(&moduledef); }
