{"command":"cd "$TMPDIR/gcm" && cat > threads2.c << 'EOF'
#include <openssl/evp.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
static double now(){struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec*1e-9;}
typedef struct { unsigned char *pt,*ct; int len; unsigned char key[16], nonce[12], aad[32], tag[16]; int aad_len; } job;
static void *worker(void *arg){
    job *j=arg;
    EVP_CIPHER_CTX *ctx=EVP_CIPHER_CTX_new();
    int len=0,fin=0;
    EVP_EncryptInit_ex(ctx, EVP_aes_128_gcm(), NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_SET_IVLEN, 12, NULL);
    EVP_EncryptInit_ex(ctx, NULL, NULL, j->key, j->nonce);
    if (j->aad_len) EVP_EncryptUpdate(ctx, NULL, &len, j->aad, j->aad_len);
    EVP_EncryptUpdate(ctx, j->ct, &len, j->pt, j->len);
    EVP_EncryptFinal_ex(ctx, j->ct+len, &fin);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_AEAD_GET_TAG, 16, j->tag);
    EVP_CIPHER_CTX_free(ctx);
    return NULL;
}
int main(){
    size_t total=60000UL*1024;
    unsigned char *pt=malloc(total), *ct=malloc(total);
    memset(pt,4,total);
    for (int nt=1; nt<=8; nt++){
        size_t chunk=total/nt;
        job jobs[16]; pthread_t th[16];
        for(int i=0;i<nt;i++){
            jobs[i].pt=pt+i*chunk; jobs[i].ct=ct+i*chunk; jobs[i].len=(int)chunk;
            memset(jobs[i].key,1,16); memset(jobs[i].nonce,2,12); jobs[i].nonce[0]=(unsigned char)i;
            memset(jobs[i].aad,3,32); jobs[i].aad_len=32;
        }
        /* warmup */
        for(int i=0;i<nt;i++) pthread_create(&th[i],NULL,worker,&jobs[i]);
        for(int i=0;i<nt;i++) pthread_join(th[i],NULL);
        double t0=now(); int iters=3;
        for(int it=0;it<iters;it++){
            for(int i=0;i<nt;i++) pthread_create(&th[i],NULL,worker,&jobs[i]);
            for(int i=0;i<nt;i++) pthread_join(th[i],NULL);
        }
        printf("%d threads independent: %.2f ms\n", nt, (now()-t0)/iters*1000);
    }
    /* persistent threads with barrier? skip */
    return 0;
}
EOF
