/* ---- GF(2^128) mul, reflected (GHASH) representation, bit 0 = x^0 of the low byte? 
   We'll use the standard NIST bit-reflection used by GCM.
   For correctness test we compare against OpenSSL, so the reduction poly must match.
   Easiest correct approach: use OpenSSL's own GHASH by encrypting zeros? 
   Actually to multiply H^k we can use a tiny software mul and verify against a known vector later.
*/

typedef struct { uint64_t lo, hi; } gf;

/* Multiply in GHASH field. Representation: the first byte of the 16-byte block is the most significant
   (GCM treats the block as a 128-bit big-endian polynomial). We'll store as hi=first 8 bytes BE, lo=last 8 BE.
*/
static gf load_be(const unsigned char b[16]) {
    gf r;
    r.hi = 0; r.lo = 0;
    for (int i = 0; i < 8; i++) r.hi = (r.hi << 8) | b[i];
    for (int i = 8; i < 16; i++) r.lo = (r.lo << 8) | b[i];
    return r;
}
static void store_be(gf r, unsigned char b[16]) {
    for (int i = 7; i >= 0; i--) { b[i] = r.hi & 0xff; r.hi >>= 8; }
    for (int i = 15; i >= 8; i--) { b[i] = r.lo & 0xff; r.lo >>= 8; }
}

/* right-shift the 128-bit value (for the reflected multiply? )
   Standard algorithm from NIST / BearSSL using the bit-reflected convention is fiddly.
   Use the straightforward schoolbook on the big-endian polynomial: 
   result = 0; for each bit of X from MSB: result = result*x XOR (bit ? Y : 0), reduce mod P.
   P = x^128 + x^7 + x^2 + x + 1.
*/
static gf gmul(gf X, gf Y) {
    gf Z = {0, 0};
    gf V = Y;
    /* iterate bits of X from MSB (bit 127 of hi) to LSB (bit 0 of lo) */
    for (int i = 0; i < 64; i++) {
        uint64_t bit = (X.hi >> (63 - i)) & 1;
        uint64_t mask = -bit;
        Z.hi ^= V.hi & mask;
        Z.lo ^= V.lo & mask;
        /* V = V * x  mod P. Multiplying by x is a left shift. Reduction if bit 127 was set. */
        uint64_t hi_msb = V.hi >> 63;
        V.hi = (V.hi << 1) | (V.lo >> 63);
        V.lo <<= 1;
        /* if original MSB set, XOR reduction constant 0xe1 into the low byte (x^7+x^2+x+1) */
        V.lo ^= (0xe1ULL) & (-hi_msb);
    }
    for (int i = 0; i < 64; i++) {
        uint64_t bit = (X.lo >> (63 - i)) & 1;
        uint64_t mask = -bit;
        Z.hi ^= V.hi & mask;
        Z.lo ^= V.lo & mask;
        uint64_t hi_msb = V.hi >> 63;
        V.hi = (V.hi << 1) | (V.lo >> 63);
        V.lo <<= 1;
        V.lo ^= (0xe1ULL) & (-hi_msb);
    }
    return Z;
}

static gf gadd(gf a, gf b) { return (gf){a.lo ^ b.lo, a.hi ^ b.hi}; }

static gf gpow(gf h, uint64_t e) {
    gf r = {0, 1}; /* 1 = x^0 which is the low bit of the last byte = lo bit 0? 
                      In big-endian polynomial, the constant term is the LSB of the last byte,
                      i.e. lo bit 0. Yes {lo:1, hi:0}. */
    /* actually wait: store_be of {lo:1, hi:0} is 00..01 which is the constant 1. Good. */
    while (e) {
        if (e & 1) r = gmul(r, h);
        h = gmul(h, h);
        e >>= 1;
    }
    return r;
