/* Bit-reflect a byte */
static inline uint8_t brev8(uint8_t b) {
    b = (b & 0xF0) >> 4 | (b & 0x0F) << 4;
    b = (b & 0xCC) >> 2 | (b & 0x33) << 2;
    b = (b & 0xAA) >> 1 | (b & 0x55) << 1;
    return b;
}

/* GHASH multiply using PCLMULQDQ.
   Our verified convention: interpret blocks as big-endian ints, but multiply with the
   bit-reflected algorithm where the second operand (H) is bit-reversed and reduction
   constant is 0xe1 << 120.

   Intel's standard GHASH CLMUL (from whitepaper) already implements exactly the
   GCM bit-reflected multiply. The usual code treats the 16-byte block in memory
   order (first byte = low address) as the xmm value via _mm_loadu_si128, which on
   little-endian loads the first byte into the low byte. That is the BIT-REFLECTED
   view of the big-endian polynomial. And H is used as-is (AES output bytes), NOT
   extra-reversed, in that convention.

   Our Python match used bitrev(H) with integer big-endian interpretation, which is
   equivalent to using raw H bytes in the little-endian/reflected xmm convention.
   So standard Intel GHASH CLMUL should work directly on raw bytes. Let's test.
*/

static __m128i gcm_reduce(__m128i X0, __m128i X1) {
    /* Intel reduction: 
       D = X1 ^ (X1 >> 1) ^ (X1 >> 2) ^ (X1 >> 7)  shifted into low, etc.
       From Intel whitepaper "Intel PCLMULQDQ instruction" carry-less mul reduction.
    */
    __m128i XMMMASK = _mm_setr_epi32(0xffffffff, 0, 0, 0); /* low 32 bits */
    /* Actually the standard algorithm from the paper:
       __m128i v1 = _mm_xor_si128(X0, _mm_slli_si128(X0, 8));
       ...
       I'll use the well-known 2-step reduction from the Linux kernel / Intel.
    */
    /* Algorithm from Intel CLMUL whitepaper Figure 6 (reduction):
       P = X1 << 1 | X1 << 2 | X1 << 7  (within the high half, shifting across)
    */
    __m128i T = _mm_srli_epi64(X1, 63);          /* carry bits of each 64 */
    __m128i X1_shift = _mm_slli_epi64(X1, 1);
    /* fold the carry of low 64 into high 64 */
    T = _mm_slli_si128(T, 8);
    X1_shift = _mm_xor_si128(X1_shift, T);

    __m128i X1_shift2 = _mm_slli_epi64(X1, 2);
    T = _mm_srli_epi64(X1, 62);
    T = _mm_slli_si128(T, 8);
    X1_shift2 = _mm_xor_si128(X1_shift2, T);

    __m128i X1_shift7 = _mm_slli_epi64(X1, 7);
    T = _mm_srli_epi64(X1, 57);
    T = _mm_slli_si128(T, 8);
    X1_shift7 = _mm_xor_si128(X1_shift7, T);

    __m128i P = _mm_xor_si128(X1_shift, _mm_xor_si128(X1_shift2, X1_shift7));
    /* now XOR P into X0 (low) and also the high-part reduction back */
    __m128i Z = _mm_xor_si128(X0, P);

    /* second phase: reduce the overflow that landed in the high 64 of the low half? 
       The paper continues:
       The shifts above only handle within the 128-bit X1 placed at the top.
       Let me use a known-good implementation instead.
    */
    (void)XMMMASK; (void)Z;
    return Z;
}

/* Known-good GHASH multiply from BearSSL / various public impls.
   Schoolbook CLMUL + reduction. Operand order: a, b are raw memory-order blocks
   (first byte at low address = low byte of xmm via loadu).
*/
static __m128i clmul_ghash_mul(__m128i a, __m128i b) {
    __m128i t0 = _mm_clmulepi64_si128(a, b, 0x00);
    __m128i t1 = _mm_clmulepi64_si128(a, b, 0x11);
    __m128i t2 = _mm_clmulepi64_si128(a, b, 0x01);
    __m128i t3 = _mm_clmulepi64_si128(a, b, 0x10);
    t2 = _mm_xor_si128(t2, t3);
    t3 = _mm_slli_si128(t2, 8);
    t2 = _mm_srli_si128(t2, 8);
    t0 = _mm_xor_si128(t0, t3);
    t1 = _mm_xor_si128(t1, t2);

