    (void)r0; (void)Y;
    return t0; /* placeholder replaced below */
}

/* Botan pclmul ghash reduction, transcribed carefully.
   From botan src/lib/utils/ghash/ghash.cpp (BSD), the function gcm_multiply_clmul:
*/
static __m128i botan_ghash_mul(__m128i H, __m128i x) {
    /* H and x are in the byte-swapped (reflected) form already? Botan swaps bytes first.
       We'll byte-reverse inputs to match botan's expected form and reverse output.
    */
