/* GHASH multiply, memory-order blocks (first byte = lowest address).
   This is the standard reflected-form PCLMUL reduction from the Intel CLMUL
   whitepaper / widely copied public implementation (e.g. the one in
   https://github.com/MaartenBaert/AES-GCM which matches NIST).
   Reduction transcribed from Intel paper "Carry-Less Multiplication Instruction"
   Figure 8, the "fast reduction" using shifts, operating on the reflected product.

   Product is 256 bits: [hi:lo] where lo holds bits 0..127 (reflected), hi bits 128..255.
   Reflected reduction polynomial R = 0xe1 << 120.
*/
static __m128i gfmul(__m128i a, __m128i b) {
    __m128i t0 = _mm_clmulepi64_si128(a, b, 0x00);
    __m128i t1 = _mm_clmulepi64_si128(a, b, 0x11);
    __m128i t2 = _mm_xor_si128(_mm_clmulepi64_si128(a, b, 0x01),
