    /* Fast reduction modulo g(x) = x^128 + x^7 + x^2 + x + 1 in reflected representation.
       From the Intel whitepaper (and openssl/crypto/modes/asm), the two-phase shift reduction:

       Phase 1: fold hi into lo by multiplying by the reduction polynomial.
       Equivalent shifts of the HIGH half:
    */
    __m128i v = hi;
