    __m128i s2 = _mm_slli_epi64(v, 2);
    __m128i s7 = _mm_slli_epi64(v, 7);
    __m128i c1 = _mm_srli_epi64(v, 63);
    __m128i c2 = _mm_srli_epi64(v, 62);
    __m128i c7 = _mm_srli_epi64(v, 57);
    __m128i carries = _mm_xor_si128(c1, _mm_xor_si128(c2, c7));
    carries = _mm_slli_si128(carries, 8);
    __m128i folded = _mm_xor_si128(s1, _mm_xor_si128(s2, s7));
    folded = _mm_xor_si128(folded, carries);
    /* folded corresponds to hi * (x + x^2 + x^7) shifted down by 128 in the reflected sense? 
