/* Exact reduction using the definition: 
   reflected product P (256 bit) reduced mod R(x) = 1 + x + x^2 + x^7 + x^128
   by multiplying the high 128 bits by (x + x^2 + x^7) and XORing, twice? 
   In the reflected representation used by GHASH (LSB = x^0), the modulus is
   x^128 + x^7 + x^2 + x + 1, and reduction of a 256-bit product is:

   Let the product be a 256-bit number with bit 0 = x^0 (LSB of low xmm).
   High 128 bits represent x^128 * hi. Since x^128 = x^7 + x^2 + x + 1,
   hi * x^128 = hi * (x^7 + x^2 + x + 1), a 135-bit value, which itself may
   need one more reduction of its top 7 bits.

   Implementing that with shifts on a 128-bit value stored little-endian in xmm
   (bit 0 = xmm low bit) :
     hi * x   = hi << 1
     hi * x^2 = hi << 2
     hi * x^7 = hi << 7
   These shifts can produce up to 7 bits above bit 127, which equal
   (those bits) * x^128 = (those bits) * (x^7+x^2+x+1), i.e. XOR those 7 bits
   shifted by 0,1,2,7 into the low part. The 7 bits are the top of the 135-bit sum.
*/
static inline __m128i shl128(__m128i v, int n) {
    /* shift left by n<64 bits across the 128-bit lane, bit 0 = low bit of low 64 */
    __m128i lo = _mm_slli_epi64(v, n);
    __m128i carry = _mm_srli_epi64(v, 64 - n);
    carry = _mm_slli_si128(carry, 8);
    /* the carry of the LOW 64 goes to the high 64; the carry of the HIGH 64 is lost (returned separately if needed) */
    return _mm_or_si128(lo, carry);
}
static inline __m128i high_carry_shl(__m128i v, int n) {
    /* the bits shifted out past bit 127 when shifting left by n */
    __m128i top = _mm_srli_epi64(v, 64 - n); /* low 64's top bits in low lane, high 64's top bits in high lane */
    /* we only want the high lane's top bits, moved to the low bits */
    top = _mm_srli_si128(top, 8);
    return top; /* low `n` bits set */
