                               _mm_clmulepi64_si128(a, b, 0x10));
    __m128i lo = _mm_xor_si128(t0, _mm_slli_si128(t2, 8));
    __m128i hi = _mm_xor_si128(t1, _mm_srli_si128(t2, 8));
    /* hi holds bits 128..255 of the product (bit 0 of hi = x^128) */

    /* first reduction: add hi * (x^7 + x^2 + x + 1) into lo, capturing overflow */
    __m128i red = hi;
    red = _mm_xor_si128(red, shl128(hi, 1));
    red = _mm_xor_si128(red, shl128(hi, 2));
    red = _mm_xor_si128(red, shl128(hi, 7));
    __m128i overflow = high_carry_shl(hi, 1);
    overflow = _mm_xor_si128(overflow, high_carry_shl(hi, 2));
    overflow = _mm_xor_si128(overflow, high_carry_shl(hi, 7));
    /* overflow is < 2^7, reduce it the same way: overflow * (x^7+x^2+x+1) has no further overflow
