    __m128i red2 = overflow;
    red2 = _mm_xor_si128(red2, shl128(overflow, 1));
    red2 = _mm_xor_si128(red2, shl128(overflow, 2));
    red2 = _mm_xor_si128(red2, shl128(overflow, 7));
    return _mm_xor_si128(lo, _mm_xor_si128(red, red2));
