/* Canonical reduction, second half done with saved pre-xor tmp3.
   Rewritten cleanly from the Intel paper listing that is reproduced in
   https://github.com/veorq/aes-brute-force and cryptodev.
*/
static __m128i gcm_mult2(__m128i a, __m128i b) {
    __m128i t0 = _mm_clmulepi64_si128(a, b, 0x00);
    __m128i t1 = _mm_clmulepi64_si128(a, b, 0x11);
    __m128i t2 = _mm_xor_si128(_mm_clmulepi64_si128(a, b, 0x01),
                               _mm_clmulepi64_si128(a, b, 0x10));
    __m128i lo = _mm_xor_si128(t0, _mm_slli_si128(t2, 8));
    __m128i hi = _mm_xor_si128(t1, _mm_srli_si128(t2, 8));

    /* shift the whole 256-bit value left by 1 (this converts from the
       "bit-reflected product" into the form the rest of the reduction expects,
       which is what the Intel snippet does first). */
    __m128i lo_shift_carry = _mm_srli_epi32(lo, 31);
    __m128i hi_shift_carry = _mm_srli_epi32(hi, 31);
    lo = _mm_slli_epi32(lo, 1);
    hi = _mm_slli_epi32(hi, 1);
    __m128i c_lo_to_hi_within = _mm_slli_si128(lo_shift_carry, 4);
    __m128i c_hi_within = _mm_slli_si128(hi_shift_carry, 4);
    __m128i c_hi_top = _mm_srli_si128(lo_shift_carry, 12);
    lo = _mm_or_si128(lo, c_lo_to_hi_within);
    hi = _mm_or_si128(hi, c_hi_within);
    hi = _mm_or_si128(hi, c_hi_top);

    __m128i s31 = _mm_slli_epi32(lo, 31);
    __m128i s30 = _mm_slli_epi32(lo, 30);
    __m128i s25 = _mm_slli_epi32(lo, 25);
    __m128i r = _mm_xor_si128(s31, _mm_xor_si128(s30, s25));
    __m128i r_low = _mm_slli_si128(r, 12);
    __m128i r_high = _mm_srli_si128(r, 4);
    lo = _mm_xor_si128(lo, r_low);

    __m128i z = _mm_xor_si128(hi, lo);
    z = _mm_xor_si128(z, _mm_srli_epi32(lo, 1));
    z = _mm_xor_si128(z, _mm_srli_epi32(lo, 2));
    z = _mm_xor_si128(z, _mm_srli_epi32(lo, 7));
    z = _mm_xor_si128(z, r_high);
    return z;
}

int main() {
    unsigned char H[16], block[16];
    /* H from earlier run */
    unsigned char Hh[] = {0xdb,0xf1,0x84,0x11,0x2e,0xb9,0x11,0x16,0x59,0x71,0x2b,0xaf,0xcf,0xf2,0xab,0x24};
