    __m128i Bv = _mm_loadu_si128((const __m128i*)block);
    printf("expected           f81f3c496e5371e9321ca1159eda49e9\n");

    dump("mult2 raw", gcm_mult2(Bv, Hv));
    dump("mult2 bswap both", bswap16(gcm_mult2(bswap16(Bv), bswap16(Hv))));
    dump("mult2 bswap H", gcm_mult2(Bv, bswap16(Hv)));
    dump("mult2 bswap B", bswap16(gcm_mult2(bswap16(Bv), Hv)));
    dump("mult2 swap args", gcm_mult2(Hv, Bv));
    dump("mult2 bswap both swap", bswap16(gcm_mult2(bswap16(Hv), bswap16(Bv))));
    return 0;
}
