/* ghash of data (must be multiple of 16), H_raw is AES output bytes.
   Uses bswap-both convention that matched. */
static void ghash_full(const unsigned char *data, size_t len, __m128i Hswap, unsigned char out[16]) {
    __m128i y = _mm_setzero_si128();
    for (size_t i = 0; i < len; i += 16) {
        __m128i b = bswap16(_mm_loadu_si128((const __m128i *)(data + i)));
        y = gcm_mult(_mm_xor_si128(y, b), Hswap);
    }
    _mm_storeu_si128((__m128i *)out, bswap16(y));
