/* partial ghash: returns Y_i = GHASH(H, chunk) i.e. the running value after the chunk,
   which equals blocks folded with powers of H. For stitching:
   Y = Y0 * H^{n1+n2+...} + Y1 * H^{n2+...} + ...
   If ghash_full returns the final y (already multiplied by H for each block),
   then Y_total = Y0 * H^{n_rest} XOR Y1 * H^{n_rest2} XOR ...
*/
typedef struct {
    const unsigned char *data;
    size_t len;
    __m128i Hswap;
    unsigned char out[16];
} gjob;

static void *gworker(void *arg) {
    gjob *j = arg;
    ghash_full(j->data, j->len, j->Hswap, j->out);
    return NULL;
}

typedef struct {
    unsigned char *in, *out;
    int len;
    unsigned char key[16];
    unsigned char iv[16];
} cjob;

static void *cworker(void *arg) {
    cjob *j = arg;
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    int len=0, fin=0;
    EVP_EncryptInit_ex(ctx, EVP_aes_128_ctr(), NULL, j->key, j->iv);
    EVP_EncryptUpdate(ctx, j->out, &len, j->in, j->len);
    EVP_EncryptFinal_ex(ctx, j->out+len, &fin);
    EVP_CIPHER_CTX_free(ctx);
    return NULL;
}

static void aes_ecb_block(const unsigned char key[16], const unsigned char in[16], unsigned char out[16]) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    int len, fin;
    EVP_EncryptInit_ex(ctx, EVP_aes_128_ecb(), NULL, key, NULL);
    EVP_CIPHER_CTX_set_padding(ctx, 0);
    EVP_EncryptUpdate(ctx, out, &len, in, 16);
    EVP_EncryptFinal_ex(ctx, out+len, &fin);
    EVP_CIPHER_CTX_free(ctx);
