        memcpy(cjs[i].key, key, 16);
        memcpy(cjs[i].iv, ctr_iv, 16);
        uint32_t c = 2 + (uint32_t)(i*(chunk/16));
        cjs[i].iv[12]=(c>>24)&0xff; cjs[i].iv[13]=(c>>16)&0xff; cjs[i].iv[14]=(c>>8)&0xff; cjs[i].iv[15]=c&0xff;
