static inline __m128i shr128(__m128i v,int n){
    __m128i hi=_mm_srli_epi64(v,n);
    __m128i carry=_mm_srli_si128(_mm_slli_epi64(v,64-n),8);
    return _mm_or_si128(hi,carry);
