/* 8-way aggregated: compute xor_i block_i * H^{8-i} with independent muls, then one reduction chain.
   For timing we just do 8 independent gcm_mults per 8 blocks (which is what aggregation enables
   instruction-level parallelism for) and one extra mul to combine — upper bound on aggregated speed. */
int main(){
    size_t n=60000UL*1024;
    unsigned char *data=malloc(n);
    memset(data,0x5a,n);
    __m128i H=_mm_set1_epi8(0x3c);
    __m128i H2=gcm_mult(H,H);
    __m128i H3=gcm_mult(H2,H);
    __m128i H4=gcm_mult(H2,H2);
    __m128i H5=gcm_mult(H4,H);
    __m128i H6=gcm_mult(H4,H2);
    __m128i H7=gcm_mult(H4,H3);
    __m128i H8=gcm_mult(H4,H4);
    (void)H5;(void)H6;(void)H7;(void)H8;
    double t0=now();
    int iters=3;
    volatile int sink=0;
    for(int it=0;it<iters;it++){
        __m128i y=_mm_setzero_si128();
        for(size_t i=0;i<n;i+=128){
            __m128i b0=bswap16(_mm_loadu_si128((const __m128i*)(data+i)));
            __m128i b1=bswap16(_mm_loadu_si128((const __m128i*)(data+i+16)));
            __m128i b2=bswap16(_mm_loadu_si128((const __m128i*)(data+i+32)));
            __m128i b3=bswap16(_mm_loadu_si128((const __m128i*)(data+i+48)));
            __m128i b4=bswap16(_mm_loadu_si128((const __m128i*)(data+i+64)));
            __m128i b5=bswap16(_mm_loadu_si128((const __m128i*)(data+i+80)));
            __m128i b6=bswap16(_mm_loadu_si128((const __m128i*)(data+i+96)));
            __m128i b7=bswap16(_mm_loadu_si128((const __m128i*)(data+i+112)));
            /* 8 independent muls */
            __m128i p0=gcm_mult(b0,H8);
            __m128i p1=gcm_mult(b1,H7);
            __m128i p2=gcm_mult(b2,H6);
            __m128i p3=gcm_mult(b3,H5);
            __m128i p4=gcm_mult(b4,H4);
            __m128i p5=gcm_mult(b5,H3);
            __m128i p6=gcm_mult(b6,H2);
            __m128i p7=gcm_mult(b7,H);
            __m128i s=_mm_xor_si128(_mm_xor_si128(p0,p1),_mm_xor_si128(p2,p3));
            s=_mm_xor_si128(s,_mm_xor_si128(_mm_xor_si128(p4,p5),_mm_xor_si128(p6,p7)));
            y=gcm_mult(y,H8);
            y=_mm_xor_si128(y,s);
        }
        sink=_mm_cvtsi128_si32(y);
    }
    printf("8-way aggregated-style 60MB: %.2f ms sink %d\n",(now()-t0)/iters*1000,sink);

    /* 4 independent streams (like 4 threads worth of ILP in one thread) */
    t0=now();
    for(int it=0;it<iters;it++){
        __m128i y0=_mm_setzero_si128(),y1=_mm_setzero_si128(),y2=_mm_setzero_si128(),y3=_mm_setzero_si128();
        size_t ch=n/4;
        for(size_t i=0;i<ch;i+=16){
            y0=gcm_mult(_mm_xor_si128(y0,bswap16(_mm_loadu_si128((const __m128i*)(data+i)))),H);
            y1=gcm_mult(_mm_xor_si128(y1,bswap16(_mm_loadu_si128((const __m128i*)(data+ch+i)))),H);
            y2=gcm_mult(_mm_xor_si128(y2,bswap16(_mm_loadu_si128((const __m128i*)(data+2*ch+i)))),H);
            y3=gcm_mult(_mm_xor_si128(y3,bswap16(_mm_loadu_si128((const __m128i*)(data+3*ch+i)))),H);
        }
        sink=_mm_cvtsi128_si32(_mm_xor_si128(_mm_xor_si128(y0,y1),_mm_xor_si128(y2,y3)));
    }
    printf("4-stream one thread 60MB: %.2f ms sink %d\n",(now()-t0)/iters*1000,sink);
    return 0;
}
