    z=_mm_xor_si128(z,_mm_srli_epi32(lo,1));
    z=_mm_xor_si128(z,_mm_srli_epi32(lo,2));
    z=_mm_xor_si128(z,_mm_srli_epi32(lo,7));
    return _mm_xor_si128(z,rh);
}

/* AES-128 key expansion (encrypt) */
static void expand128(const unsigned char key[16], __m128i rk[11]){
    rk[0]=_mm_loadu_si128((const __m128i*)key);
    __m128i t=rk[0];
    #define EXP(i, rcon) do{ \
        __m128i s=_mm_aeskeygenassist_si128(t, rcon); \
        s=_mm_shuffle_epi32(s, 0xff); \
        t=_mm_xor_si128(t, _mm_slli_si128(t,4)); \
        t=_mm_xor_si128(t, _mm_slli_si128(t,4)); \
        t=_mm_xor_si128(t, _mm_slli_si128(t,4)); \
        t=_mm_xor_si128(t, s); \
        rk[i]=t; \
    } while(0)
    EXP(1,0x01); EXP(2,0x02); EXP(3,0x04); EXP(4,0x08); EXP(5,0x10);
    EXP(6,0x20); EXP(7,0x40); EXP(8,0x80); EXP(9,0x1b); EXP(10,0x36);
    #undef EXP
}

static inline __m128i aes128(__m128i b, const __m128i rk[11]){
    b=_mm_xor_si128(b, rk[0]);
    b=_mm_aesenc_si128(b, rk[1]);
    b=_mm_aesenc_si128(b, rk[2]);
    b=_mm_aesenc_si128(b, rk[3]);
    b=_mm_aesenc_si128(b, rk[4]);
    b=_mm_aesenc_si128(b, rk[5]);
    b=_mm_aesenc_si128(b, rk[6]);
    b=_mm_aesenc_si128(b, rk[7]);
    b=_mm_aesenc_si128(b, rk[8]);
    b=_mm_aesenc_si128(b, rk[9]);
    return _mm_aesenclast_si128(b, rk[10]);
}

/* 8-way CTR + running GHASH. Counters are big-endian in the last 4 bytes. */
static void ctr_ghash_8(const __m128i rk[11], __m128i Hswap,
                        const unsigned char *in, unsigned char *out, size_t nblocks,
                        __m128i *y_io, unsigned char ctr_iv[16]){
    __m128i y=*y_io;
    uint32_t ctr = ((uint32_t)ctr_iv[12]<<24)|((uint32_t)ctr_iv[13]<<16)|((uint32_t)ctr_iv[14]<<8)|ctr_iv[15];
    __m128i base;
    unsigned char ivtmp[16];
    memcpy(ivtmp, ctr_iv, 12);
    memset(ivtmp+12, 0, 4);
    base=_mm_loadu_si128((const __m128i*)ivtmp);
    /* byte-swap mask to increment? We'll build counter blocks explicitly for correctness first. */
    size_t i=0;
    while(i+8<=nblocks){
        __m128i c[8], p[8];
        for(int k=0;k<8;k++){
            unsigned char cb[16];
            memcpy(cb, ctr_iv, 12);
            uint32_t v=ctr+(uint32_t)k;
            cb[12]=v>>24; cb[13]=v>>16; cb[14]=v>>8; cb[15]=v;
            c[k]=_mm_loadu_si128((const __m128i*)cb);
            p[k]=_mm_loadu_si128((const __m128i*)(in+16*(i+k)));
        }
        ctr+=8;
        __m128i ks[8];
        for(int k=0;k<8;k++) ks[k]=_mm_xor_si128(c[k], rk[0]);
        for(int r=1;r<=9;r++) for(int k=0;k<8;k++) ks[k]=_mm_aesenc_si128(ks[k], rk[r]);
        for(int k=0;k<8;k++) ks[k]=_mm_aesenclast_si128(ks[k], rk[10]);
        for(int k=0;k<8;k++){
            __m128i ct=_mm_xor_si128(p[k], ks[k]);
            _mm_storeu_si128((__m128i*)(out+16*(i+k)), ct);
            y=gcm_mult(_mm_xor_si128(y, bswap16(ct)), Hswap);
        }
        i+=8;
    }
    while(i<nblocks){
        unsigned char cb[16];
        memcpy(cb, ctr_iv, 12);
        cb[12]=ctr>>24; cb[13]=ctr>>16; cb[14]=ctr>>8; cb[15]=ctr;
