    unsigned char j0[16]; memcpy(j0, nonce, 12); j0[12]=0; j0[13]=0; j0[14]=0; j0[15]=1;
    unsigned char ek[16]; _mm_storeu_si128((__m128i*)ek, aes128(_mm_loadu_si128((const __m128i*)j0), rk));
